-- @setup
CREATE TEMPORARY VIEW c18_a AS SELECT * FROM VALUES
  (1, 10, TIMESTAMP '2024-01-01 00:00:00'), (1, 20, TIMESTAMP '2024-01-01 00:03:00'),
  (1, 30, TIMESTAMP '2024-01-01 00:20:00'), (2, 40, TIMESTAMP '2024-01-01 00:01:00'),
  (3, 50, TIMESTAMP '2024-01-01 00:30:00'), (4, CAST(NULL AS INT), CAST(NULL AS TIMESTAMP)) AS c18_a(k, v, ts);

-- @setup
CREATE TEMPORARY VIEW c18_b AS SELECT * FROM VALUES (1, 'x'), (2, 'y'), (3, CAST(NULL AS STRING)), (5, 'z')
  AS c18_b(k, s);

-- @setup
CREATE TEMPORARY VIEW c18_ab AS SELECT a.k, a.v, a.ts, b.s FROM c18_a a JOIN c18_b b ON a.k = b.k;

